SELECT AVG(value_1) AS value, COUNT(value_1) AS cnt FROM (SELECT time, CAST(metric_0001 AS DOUBLE PRECISION) AS value_1, CAST(metric_0002 AS DOUBLE PRECISION) AS value_2, CAST(metric_0003 AS DOUBLE PRECISION) AS value_3, CAST(metric_0004 AS DOUBLE PRECISION) AS value_4 FROM wide1000) s WHERE value_2 > 10
